export type TestCase = TestCase_Serialize | TestCase_Deserialize;

/**
 *  A fully-loaded Test Case for the editor: steps parsed from the XML blob,
 *  preconditions flattened to plain text. `id` doubles as update_id when the
 *  editor saves.
 */
export type TestCaseFull = {
	id: number,
	title: string,
	tags: string,
	automation_status: string,
	steps: Step[],
	/**
	 *  Real ADO step ids (document order, aligned with `steps`) - the runner
	 *  needs them to build iterationDetails.
	 */
	step_ids: string[],
	/**
	 *  The Steps field EXACTLY as Azure DevOps holds it.
	 * 
	 *  `steps` above is a lossy read: parse_steps_xml strips every tag, so
	 *  bold, links and embedded screenshots do not survive it. Writing that
	 *  back would delete them from the work item. Keeping the original
	 *  lets a save ask "did the user actually change the steps?" and, when
	 *  the answer is no, leave the field out of the patch entirely.
	 */
	steps_xml: string,
	module_value: string,
	preconditions: string,
};

export type TestCaseSummary = {
	id: number,
	title: string,
	tags: string,
	automation_status: string,
};

export type TestCase_Deserialize = {
	title: string,
	steps: Step[],
	/**  Semicolon-separated. */
	tags: string,
	/**  "Not Automated" or "Planned". */
	automation_status: string,
	module_value: string,
	preconditions: string,
	/**  When set, update this existing work item instead of creating a new one. */
	update_id: number | null,
	/**
	 *  In-app note that round-trips through the JSON export/import but is
	 *  NEVER sent to Azure DevOps (no ADO field mapping reads it).
	 *  Absent from serialized output when empty, so tools that round-trip
	 *  a draft do not inject a field the caller never wrote (feedback:
	 *  a transform must be idempotent in shape).
	 */
	comment?: string,
	/**
	 *  Context for whoever REVIEWS this case - what in the spec it comes
	 *  from, which acceptance criterion it covers, what was deliberately
	 *  left out. Written by hand or by an assistant, read in the browser
	 *  page during review, and rendered as markdown there.
	 * 
	 *  Like `comment`, it round-trips through the JSON and is NEVER sent
	 *  to Azure DevOps. Two tests hold that: the `NoCommentInBody` matcher
	 *  on the create mock, and `app_only_fields_never_reach_a_request_body`,
	 *  which scans `ado/endpoints.rs` so the rule also covers the update
	 *  path and any write function added later.
	 * 
	 *  The two fields are separate on purpose: `comment` is the reviewer's
	 *  own scratchpad and is editable in the page; this is the reference
	 *  material they read while writing one.
	 */
	reviewer_notes?: string,
	/**
	 *  This case's 1-based position when the set is read AGAINST THE SPEC -
	 *  cases walking down the document, so a reviewer scrolls the spec and
	 *  the file together. Stamped by the optimizer from the order the
	 *  draft was written in; app-only, like the two notes above - never
	 *  sent to Azure DevOps (`app_only_fields_never_reach_a_request_body`
	 *  covers it by scanning the write path).
	 */
	spec_order?: number | null,
	/**
	 *  This case's 1-based position when the set is run BY A TESTER -
	 *  grouped so cases sharing a setup run together and the environment
	 *  changes as few times as possible. Stamped by the optimizer's
	 *  grouping pass. Both orders live in the same file so neither reading
	 *  costs the other; the array order is just whichever one the file was
	 *  last saved in.
	 */
	tester_order?: number | null,
};

export type TestCase_Serialize = {
	title: string,
	steps: Step[],
	/**  Semicolon-separated. */
	tags: string,
	/**  "Not Automated" or "Planned". */
	automation_status: string,
	module_value: string,
	preconditions: string,
	/**  When set, update this existing work item instead of creating a new one. */
	update_id: number | null,
	/**
	 *  In-app note that round-trips through the JSON export/import but is
	 *  NEVER sent to Azure DevOps (no ADO field mapping reads it).
	 *  Absent from serialized output when empty, so tools that round-trip
	 *  a draft do not inject a field the caller never wrote (feedback:
	 *  a transform must be idempotent in shape).
	 */
	comment?: string,
	/**
	 *  Context for whoever REVIEWS this case - what in the spec it comes
	 *  from, which acceptance criterion it covers, what was deliberately
	 *  left out. Written by hand or by an assistant, read in the browser
	 *  page during review, and rendered as markdown there.
	 * 
	 *  Like `comment`, it round-trips through the JSON and is NEVER sent
	 *  to Azure DevOps. Two tests hold that: the `NoCommentInBody` matcher
	 *  on the create mock, and `app_only_fields_never_reach_a_request_body`,
	 *  which scans `ado/endpoints.rs` so the rule also covers the update
	 *  path and any write function added later.
	 * 
	 *  The two fields are separate on purpose: `comment` is the reviewer's
	 *  own scratchpad and is editable in the page; this is the reference
	 *  material they read while writing one.
	 */
	reviewer_notes?: string,
	/**
	 *  This case's 1-based position when the set is read AGAINST THE SPEC -
	 *  cases walking down the document, so a reviewer scrolls the spec and
	 *  the file together. Stamped by the optimizer from the order the
	 *  draft was written in; app-only, like the two notes above - never
	 *  sent to Azure DevOps (`app_only_fields_never_reach_a_request_body`
	 *  covers it by scanning the write path).
	 */
	spec_order?: number | null,
	/**
	 *  This case's 1-based position when the set is run BY A TESTER -
	 *  grouped so cases sharing a setup run together and the environment
	 *  changes as few times as possible. Stamped by the optimizer's
	 *  grouping pass. Both orders live in the same file so neither reading
	 *  costs the other; the array order is just whichever one the file was
	 *  last saved in.
	 */
	tester_order?: number | null,
};

export type TestPlan = {
	id: number,
	name: string,
	area_path: string,
	root_suite_id: number | null,
};

export type TestPoint = {
	point_id: number,
	test_case_id: number | null,
	test_case_name: string,
	config_name: string,
	tester: string,
	last_outcome: string,
	last_run_id: number | null,
	last_result_id: number | null,
};

/**
 *  A single step inside a job - the level ADO's log view shows, and the
 *  level a failure is actually pinned to.
 */
export type TimelineTask = {
	name: string,
	/**  "completed" | "inProgress" | "pending". */
	state: string,
	/**  "succeeded" | "failed" | "skipped" | "abandoned" | "" while running. */
	result: string,
	started: string,
	finished: string,
	/**
	 *  Error/warning text ADO attached to this step - the summary you get
	 *  without fetching anything.
	 */
	issues: string[],
	/**
	 *  Timeline log id, when this step produced output. 0 = none yet (a
	 *  pending step, or one whose logs have been cleaned up).
	 */
	log_id: number,
};

/**
 *  Emitted while an update package downloads, so the banner can show a bar
 *  instead of a spinner that says nothing about how long is left.
 * 
 *  `total` is exact - the size the release feed gives. `downloaded` is that
 *  share of it implied by `percent`, which Velopack floors to the nearest
 *  5%, so it steps rather than counts. Bytes are f64 because u64 is not
 *  exportable over these bindings; an installer is nowhere near the limit
 *  where a double stops being exact.
 */
export type UpdateProgress = {
	percent: number,
	downloaded: number | null,
	total: number | null,
};

/**
 *  The outcome of an update check - all THREE of them.
 * 
 *  This used to be an Option, so "a newer version exists", "you are up to
 *  date", "this build cannot update itself" and "the feed was unreachable"
 *  collapsed into two answers. The app told the last two "You are on the
 *  latest version", which is a claim it had not checked and could not make.
 */
export type UpdateStatus = {
	/**  The newer version, when there is one. */
	available: string | null,
	/**
	 *  Why no check happened. When this is set, `available` being None
	 *  means "unknown", NOT "up to date".
	 */
	blocked: string | null,
};

/**
 *  Emitted when the JSON file an import is following changes on disk -
 *  once per real content change, never on a save that rewrote the same
 *  bytes. `stamp` is the new fingerprint (see filewatch.rs).
 */
export type WatchedFileChanged = {
	path: string,
	stamp: string,
};

/**
 *  Emitted when work items have been newly assigned to the signed-in
 *  user. The frontend decides how to surface them: a toast when the app
 *  has focus, an OS notification when it doesn't.
 */
export type WorkAssigned = {
	items: AssignedItem[],
};

export type WorkComment = {
	id: number,
	text: string,
	created_by: string,
	created_date: string,
	avatar_url: string,
};

export type WorkItemDetail = {
	id: number,
	title: string,
	work_item_type: string,
	state: string,
	assigned_to: string,
	assigned_to_unique: string,
	activity: string,
	tags: string,
	area_path: string,
	iteration_path: string,
	remaining_work: number | null,
	completed_work: number | null,
	original_estimate: number | null,
	start_date: string,
	target_date: string,
	/**
	 *  Description (or ReproSteps for Bugs) flattened to plain text for the
	 *  editor; saving wraps it back into a div like v1's preconditions.
	 */
	description_text: string,
	/**
	 *  The same field's RAW HTML, so the editor can convert it to markdown
	 *  and preserve the formatting ADO stored (bold, lists, links...).
	 */
	description_html: string,
	/**
	 *  Which field the description came from (System.Description or
	 *  Microsoft.VSTS.TCM.ReproSteps) so the save writes the right one.
	 */
	description_field: string,
	/**
	 *  The process's extra form pages (Bug: RCA, Preventive Measures...)
	 *  with every visible field on them, shown as editable tabs.
	 */
	extra_pages: ExtraPage[],
	/**
	 *  Why extra_pages is empty when the layout lookup failed - surfaced in
	 *  the drawer so a permissions/endpoint problem is visible, not silent.
	 */
	extra_pages_error: string | null,
	/**
	 *  Authenticated attachment images from the rich-text fields, downloaded
	 *  with the token so the preview can swap URLs for data: URIs (a plain
	 *  <img> gets 401). Field values themselves stay byte-faithful.
	 */
	inline_images: InlineImage[],
};

/**  One entry in a work item's history: everything one save changed. */
export type WorkRevision = {
	rev: number,
	by: string,
	avatar_url: string,
	/**  ISO 8601; empty if ADO gave no usable date. */
	at: string,
	fields: FieldChange[],
	links_added: string[],
	links_removed: string[],
	/**
	 *  Pulled out of `fields` so the timeline can lead with the state
	 *  move, which is what people scan history for.
	 */
	state_from: string,
	state_to: string,
	comment_added: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

